const $=s=>document.querySelector(s);let me,maps=[],players=[];const roles=['Duelista','Controlador','Iniciador','Sentinela','Flex'];const VERSION='V0.9.6 LOCAL';let mapData={},agentData={};
async function api(u,o={}){const r=await fetch(u,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(o.headers||{})},...o}),d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||`Erro ${r.status}`);return d}function esc(x=''){return String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function applyVisualData(m,a){(m.data||[]).forEach(x=>mapData[x.displayName]=x.listViewIcon||x.splash);(a.data||[]).forEach(x=>agentData[x.displayName]={icon:x.displayIcon,portrait:x.fullPortrait})}
async function loadVisualData(){try{const c=JSON.parse(localStorage.getItem('vortex_visuals')||'null');if(c){applyVisualData(c.maps,c.agents);return}const [m,a]=await Promise.all([fetch('https://valorant-api.com/v1/maps?language=pt-BR').then(x=>x.json()),fetch('https://valorant-api.com/v1/agents?isPlayableCharacter=true&language=pt-BR').then(x=>x.json())]);applyVisualData(m,a);localStorage.setItem('vortex_visuals',JSON.stringify({maps:m,agents:a}))}catch(e){}}
function canCoach(){return me.role==='admin'||me.role==='coach'||(me.role==='both'&&me.activeMode==='coach')}function canPlayer(){return me.role==='player'||(me.role==='both'&&me.activeMode==='player')}
function modeLabel(){return me.role==='admin'?'ADMIN':me.activeMode==='coach'?'COACH':'PLAYER'}
function startLiveUpdates(){if(window.vortexEvents)return;window.vortexEvents=new EventSource('/api/events');window.vortexEvents.onmessage=()=>{if(document.hidden)return;if(typeof window.vortexRefresh==='function')window.vortexRefresh()};}
async function boot(){me=(await api('/api/me')).user;if(me){home();startLiveUpdates();loadVisualData().then(()=>dashboardPage())}else{login();loadVisualData()}}
function login(){$('#app').innerHTML=`<div class="login"><div class="login-bg"></div><div class="login-card"><img class="login-logo" src="/assets/vortex-logo.png" alt="Vortex Esports Team"><span class="login-kicker">VALORANT TEAM MANAGEMENT</span><h1>ÁREA PRIVADA</h1><p>Entra para gerir a Vortex, consultar estatísticas e preparar a competição.</p><form id="f"><label>USERNAME</label><input name="username" placeholder="Username" required><label>PASSWORD</label><input type="password" name="password" placeholder="Password" required><button class="btn full">ENTRAR NO PAINEL</button></form><small id="e"></small></div></div>`;$('#f').onsubmit=async e=>{e.preventDefault();try{me=(await api('/api/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))})).user;home()}catch(x){$('#e').textContent=x.message}}}
function home(){$('#app').innerHTML=`<button class="menu-dot" id="menuBtn" aria-label="Abrir menu"><span></span><span></span><span></span></button><aside id="side" class="side"><div class="side-brand"><img src="/assets/vortex-logo.png" alt="Vortex Esports Team"><div><b>VORTEX</b><small>ESPORTS TEAM</small></div></div><div class="side-user"><div class="avatar">${esc(me.displayName[0]||'V')}</div><div><b>${esc(me.displayName)}</b><small>${modeLabel()}${me.role==='both'?' · conta dupla':''}</small></div></div><nav><button onclick="dashboardPage()">⌂ <span>Dashboard</span></button><button onclick="mapsPage()">◈ <span>Map Pool</span></button>${canCoach()?`<button onclick="lineGeneralPage()">♙ <span>Line Geral</span></button><button onclick="statsPage()">▥ <span>Splits</span></button><button onclick="trainingPage()">◈ <span>Jogos de Treino</span></button>`:''}<button onclick="analyzerPage()">◉ <span>Analisador</span></button>${(canPlayer()||canCoach())?`<button onclick="rankedPage()">↗ <span>Rankeds</span></button>`:''}<button onclick="achievementsPage()">🏆 <span>Palmarés</span></button>${me.role==='admin'?'<button onclick="playersPage()">☷ <span>Credenciais</span></button>':''}<button onclick="settingsPage()">⚙ <span>Definições</span></button></nav><div class="side-bottom">${me.role==='both'?`<button onclick="switchMode()">⇄ <span>Mudar para ${me.activeMode==='player'?'Coach':'Player'}</span></button>`:''}<button id="out">↪ <span>Sair</span></button></div></aside><div id="overlay"></div><main class="main"><header class="top"><div><div class="eyebrow">VORTEX / VALORANT · ${VERSION}</div><h1 id="pageTitle">Dashboard</h1></div><div class="top-right"><span class="status"><i></i> Modo ${modeLabel()}</span></div></header><div id="c"></div></main>`;$('#menuBtn').onclick=()=>document.body.classList.toggle('menu-open');$('#overlay').onclick=()=>document.body.classList.remove('menu-open');$('#out').onclick=async()=>{await api('/api/logout',{method:'POST'});location.reload()};dashboardPage()}
async function switchMode(){const mode=me.activeMode==='player'?'coach':'player';me=(await api('/api/mode',{method:'POST',body:JSON.stringify({mode})})).user;home()}
async function settingsPage(){window.vortexRefresh=settingsPage;$('#pageTitle').textContent='Definições';$('#c').innerHTML=`<div class="page-intro"><div><span class="eyebrow">CONTA</span><h2>Segurança e preferências</h2><p>Altera a tua palavra-passe e, quando aplicável, muda entre os modos Player e Coach.</p></div></div><div class="settings-grid"><div class="card"><span class="eyebrow">SEGURANÇA</span><h2>Alterar palavra-passe</h2><form id="pw" class="form-grid"><input name="currentPassword" type="password" placeholder="Palavra-passe atual" required><input name="newPassword" type="password" placeholder="Nova palavra-passe (mín. 6)" minlength="6" required><input name="confirmPassword" type="password" placeholder="Confirmar nova palavra-passe" minlength="6" required><button class="btn">Guardar nova palavra-passe</button></form></div>${me.role==='both'?`<div class="card"><span class="eyebrow">FUNÇÃO ATIVA</span><h2>Modo ${modeLabel()}</h2><p class="muted">A tua conta tem acesso a Player e Coach. Mantém os menus separados para não misturar as funções.</p><button class="btn" onclick="switchMode()">Mudar para ${me.activeMode==='player'?'Coach':'Player'}</button></div>`:''}</div>`;$('#pw').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);if(f.get('newPassword')!==f.get('confirmPassword'))return alert('As novas palavras-passe não coincidem.');try{await api('/api/password',{method:'POST',body:JSON.stringify({currentPassword:f.get('currentPassword'),newPassword:f.get('newPassword')})});alert('Palavra-passe alterada com sucesso.');e.target.reset()}catch(x){alert(x.message)}}}

function mapCard(m){const img=mapData[m.name];return `<article class="map-card ${m.active?'selected':''}">${img?`<img class="map-image" src="${img}" loading="lazy" decoding="async" alt="${esc(m.name)}">`:''}<div class="map-overlay"></div><div class="map-content"><div class="map-heading"><span class="map-index">MAPA ${String(m.id).padStart(2,'0')}</span><h3>${esc(m.name)}</h3></div><span class="pill ${m.active?'on':''}">${m.active?'NA ROTAÇÃO':'FORA'}</span><div class="map-actions">${canCoach()?`<button class="icon-btn" onclick="rot(${m.id},${!m.active})">${m.active?'−':'+'}</button><button class="small-btn" onclick="line(${m.id})">Line do mapa</button>`:''}</div></div></article>`}
async function dashboardPage(){window.vortexRefresh=dashboardPage;try{maps=await api('/api/maps');const active=maps.filter(x=>x.active),gl=await api('/api/general-lineup');$('#pageTitle').textContent='Dashboard';$('#c').innerHTML=`<section class="hero"><div><span class="eyebrow">PAINEL DA EQUIPA</span><h2>Uma central para a Vortex.</h2><p>Line geral, rotação, splits, rankeds e palmarés organizados num só espaço.</p></div><div class="hero-stat"><b>${active.length}</b><span>mapas na rotação</span></div></section><div class="stats-grid"><div class="metric"><span>Line definida</span><b>${gl.filter(x=>x.player_id).length}/5</b></div><div class="metric"><span>Map Pool</span><b>${maps.length}</b></div><div class="metric"><span>Versão</span><b>${VERSION}</b></div></div><div class="section-head"><div><span class="eyebrow">LINE PRINCIPAL</span><h2>Line Geral</h2></div></div><div class="line-preview">${gl.map(x=>`<div class="player-mini"><span>${x.slot}</span><div class="avatar">${x.display_name?esc(x.display_name[0]):'?'}</div><div><b>${esc(x.display_name||'Por definir')}</b><small>${esc(x.role||'Função')}</small></div></div>`).join('')}</div><div class="section-head"><div><span class="eyebrow">MAP POOL</span><h2>Rotação atual</h2></div></div><div class="map-grid dashboard-map-grid">${active.map(mapCard).join('')||'<div class="empty">Nenhum mapa na rotação.</div>'}</div>`}catch(e){$('#c').innerHTML=`<div class="card error-card"><span class="eyebrow">ERRO DO DASHBOARD</span><h2>Não foi possível carregar os dados</h2><p>${esc(e.message||'Erro desconhecido')}</p><button class="btn" onclick="dashboardPage()">Tentar novamente</button></div>`}}
async function mapsPage(){window.vortexRefresh=mapsPage;maps=await api('/api/maps');$('#pageTitle').textContent='Map Pool';const active=maps.filter(x=>x.active);if(canPlayer()&&!canCoach()){$('#c').innerHTML=`<div class="page-intro"><div><span class="eyebrow">PLAYER</span><h2>Agentes por mapa</h2><p>Escolhe os agentes que queres usar em cada mapa da rotação. Podes selecionar vários agentes por mapa.</p></div></div><div class="player-map-list">${active.map(x=>playerMapCard(x)).join('')||'<div class="empty">O Coach ainda não colocou nenhum mapa na rotação.</div>'}</div>`;return}$('#c').innerHTML=`<div class="page-intro"><div><span class="eyebrow">MAPAS</span><h2>Rotação da equipa</h2><p>O Coach escolhe manualmente os mapas. A line geral é a base e a line do mapa serve apenas para substituições.</p></div></div><div class="map-grid">${maps.map(mapCard).join('')}</div>${canPlayer()?'<div id="playerMaps"></div>':''}`;if(canPlayer())myMaps()}
function playerMapCard(x){const agents=x.agents||[];const img=mapData[x.name];const agentStrip=agents.length?`<div class="selected-agents">${agents.map(a=>agentData[a]?.icon?`<span class="agent-tag"><img src="${agentData[a].icon}" loading="lazy" alt=""><b>${esc(a)}</b></span>`:`<span class="agent-tag"><b>${esc(a)}</b></span>`).join('')}</div>`:'<div class="no-agents">Ainda não escolheste agentes para este mapa.</div>';return `<article class="player-map-wide">${img?`<img class="player-map-wide-image" src="${img}" loading="lazy" decoding="async" alt="${esc(x.name)}">`:''}<div class="player-map-wide-overlay"></div><div class="player-map-wide-content"><div class="player-map-title"><div class="player-map-heading"><span class="map-index">MAPA ${String(x.id).padStart(2,'0')}</span><h3>${esc(x.name)}</h3></div><span class="pill on">NA ROTAÇÃO</span></div><div class="player-map-agents"><div><span class="agent-section-label">AGENTES PREFERIDOS</span>${agentStrip}</div><button class="agent-pick-btn agent-pick-btn-big" onclick='agent(${x.id},${JSON.stringify(x.role||'Sem função')},${JSON.stringify(agents)})'>${agents.length?'✎ EDITAR AGENTES':'＋ ESCOLHER AGENTES'}</button></div></div></article>`}
async function rot(id,a){await api('/api/maps/'+id+'/rotation',{method:'POST',body:JSON.stringify({active:a})});mapsPage()}
async function lineGeneralPage(){window.vortexRefresh=lineGeneralPage;players=await api('/api/players');const old=await api('/api/general-lineup');$('#pageTitle').textContent='Line Geral';$('#c').innerHTML=`<div class="page-intro"><div><span class="eyebrow">EQUIPA PRINCIPAL</span><h2>Line Geral</h2><p>Define os cinco jogadores e a função. Esta é a line usada por defeito em todos os mapas.</p></div></div><div class="jersey-line">${[1,2,3,4,5].map(i=>{const s=old.find(x=>x.slot===i)||{};return `<div class="jersey-player"><div class="jersey"><span class="jersey-number">${i}</span><strong>${esc(s.display_name||'—')}</strong></div><div class="jersey-role">${esc(s.role||'Função')}</div>${canCoach()?`<div class="jersey-edit"><select id="gp${i}"><option value="">— jogador —</option>${players.map(p=>`<option value="${p.id}" ${String(s.player_id)===String(p.id)?'selected':''}>${esc(p.display_name)}</option>`).join('')}</select><select id="gr${i}">${roles.map(x=>`<option ${s.role===x?'selected':''}>${x}</option>`).join('')}</select></div>`:''}</div>`}).join('')}</div>${canCoach()?`<div class="form-actions centered"><button class="btn" onclick="saveGeneral()">Guardar Line Geral</button></div>`:''}<div class="coach-strip"><span>STAFF TÉCNICO</span><b>MitzZ</b><small>Responsável técnico</small></div>`}
async function saveGeneral(){const slots=[1,2,3,4,5].map(i=>({slot:i,playerId:$('#gp'+i).value||null,role:$('#gr'+i).value}));if(new Set(slots.filter(x=>x.playerId).map(x=>x.playerId)).size<slots.filter(x=>x.playerId).length)return alert('Não podes colocar o mesmo jogador duas vezes.');await api('/api/general-lineup',{method:'POST',body:JSON.stringify({slots})});dashboardPage()}
async function line(id){players=players.length?players:await api('/api/players');const old=await api('/api/lineups/'+id),effective=await api('/api/maps/'+id+'/effective-lineup'),map=maps.find(x=>x.id===id);$('#pageTitle').textContent='Line do mapa';$('#c').innerHTML=`<div class="page-intro"><div><span class="eyebrow">${esc(map?.name||'Mapa')}</span><h2>Line e preferências</h2><p>Aqui o Coach vê a line efetiva deste mapa e o agente que cada jogador prefere usar.</p></div></div><div class="card"><div class="map-line-view">${effective.map(x=>`<div class="line-row"><div class="role-badge">${x.slot}<small>Slot</small></div><div class="line-player-info"><b>${esc(x.display_name||'Por definir')}</b><span>${esc(x.role||'Função')}</span></div><div class="agent-preview">${(x.agents||[]).map(a=>agentData[a]?.icon?`<span class="agent-tag"><img src="${agentData[a].icon}" alt=""><b>${esc(a)}</b></span>`:`<span class="agent-tag"><b>${esc(a)}</b></span>`).join('')||'<span>Agentes não escolhidos</span>'}${canCoach()&&x.player_id?`<button class="btn small" onclick='coachAgent(${id},${x.player_id},${JSON.stringify(x.role)},${JSON.stringify(x.agents||[])})'>✎ Agentes</button>`:''}</div></div>`).join('')||'<div class="empty">Nenhum jogador atribuído.</div>'}</div>${canCoach()?`<div class="section-head"><div><span class="eyebrow">SUBSTITUIÇÕES</span><h2>Editar Line deste mapa</h2></div></div>${[1,2,3,4,5].map(i=>{const sv=old.find(x=>x.slot===i)||{};return `<div class="line-row"><div class="role-badge">${i}<small>Slot</small></div><select id="mp${i}"><option value="">— usar line geral —</option>${players.map(p=>`<option value="${p.id}" ${String(sv.player_id)===String(p.id)?'selected':''}>${esc(p.display_name)}</option>`).join('')}</select><select id="mr${i}">${roles.map(x=>`<option ${sv.role===x?'selected':''}>${x}</option>`).join('')}</select></div>`}).join('')}<div class="form-actions"><button class="btn" onclick="saveLine(${id})">Guardar substituição</button><button class="btn secondary" onclick="clearLine(${id})">Usar Line Geral</button></div>`:''}<div class="form-actions"><button class="btn ghost" onclick="mapsPage()">Voltar</button></div></div>`}
async function saveLine(id){const slots=[1,2,3,4,5].map(i=>({slot:i,playerId:$('#mp'+i).value||null,role:$('#mr'+i).value})).filter(x=>x.playerId);if(new Set(slots.map(x=>x.playerId)).size!==slots.length)return alert('Não podes repetir jogadores no mesmo mapa.');await api('/api/lineups/'+id,{method:'POST',body:JSON.stringify({slots})});mapsPage()}async function clearLine(id){await api('/api/lineups/'+id,{method:'DELETE'});mapsPage()}
async function myMaps(){const r=await api('/api/my-maps');$('#playerMaps').innerHTML=`<div class="section-head"><div><span class="eyebrow">PLAYER</span><h2>Os meus mapas</h2></div></div><div class="player-map-list">${r.length?r.map(x=>playerMapCard(x)).join(''):'<div class="empty">O Coach ainda não colocou nenhum mapa na rotação.</div>'}</div>`}
async function agent(id,role,current=[]){const a=await api('/api/agents/all'),chosen=new Set(current||[]);const old=document.querySelector('.agent-modal');if(old)old.remove();document.body.insertAdjacentHTML('beforeend',`<div class="agent-modal modal-card"><div class="agent-modal-inner"><button class="icon-btn agent-close" onclick="document.querySelector('.agent-modal')?.remove()">×</button><span class="eyebrow">ESCOLHA DO PLAYER</span><h2>Agentes preferidos para este mapa</h2><p class="muted">A tua função é <b>${esc(role)}</b>, mas podes escolher <b>qualquer agente</b>. Seleciona um ou vários.</p><div class="agent-grid">${a.map(x=>`<button class="agent-choice ${chosen.has(x)?'picked':''}" data-agent="${esc(x)}" onclick="this.classList.toggle('picked')">${agentData[x]?.portrait?`<img src="${agentData[x].portrait}" loading="lazy" decoding="async">`:''}<span>${esc(x)}</span></button>`).join('')}</div><div class="form-actions centered"><button class="btn" onclick="saveAgents(${id})">Guardar agentes selecionados</button></div></div></div>`) }
async function coachAgent(mapId,playerId,role,current=[]){const a=await api('/api/agents/all'),chosen=new Set(current||[]);const old=document.querySelector('.agent-modal');if(old)old.remove();document.body.insertAdjacentHTML('beforeend',`<div class="agent-modal modal-card"><div class="agent-modal-inner"><button class="icon-btn agent-close" onclick="document.querySelector('.agent-modal')?.remove()">×</button><span class="eyebrow">COACH</span><h2>Agentes do jogador</h2><p class="muted">Seleciona um ou vários agentes.</p><div class="agent-grid">${a.map(x=>`<button class="agent-choice ${chosen.has(x)?'picked':''}" data-agent="${esc(x)}" onclick="this.classList.toggle('picked')">${agentData[x]?.portrait?`<img src="${agentData[x].portrait}" loading="lazy">`:''}<span>${esc(x)}</span></button>`).join('')}</div><div class="form-actions centered"><button class="btn" onclick="saveCoachAgents(${mapId},${playerId})">Guardar agentes</button></div></div></div>`)}
async function saveCoachAgents(mapId,playerId){const agents=[...document.querySelectorAll('.agent-choice.picked')].map(x=>x.dataset.agent);await api('/api/lineups/'+mapId+'/agent',{method:'POST',body:JSON.stringify({playerId,agents})});document.querySelector('.agent-modal')?.remove();line(mapId)}
async function saveAgents(id){const agents=[...document.querySelectorAll('.agent-choice.picked')].map(x=>x.dataset.agent);await api('/api/lineups/'+id+'/agent',{method:'POST',body:JSON.stringify({agents})});document.querySelector('.agent-modal')?.remove();mapsPage()}

async function statsPage(){window.vortexRefresh=statsPage;const splits=await api('/api/splits');$('#pageTitle').textContent='Splits & Estatísticas';$('#c').innerHTML=`${canCoach()?`<div class="card"><span class="eyebrow">NOVO SPLIT</span><h2>Criar Split</h2><form id="sf" class="form-grid"><input name="name" placeholder="Nome do campeonato / split" required><input name="season" placeholder="Época / ano"><input name="startDate" type="date" title="Início"><input name="endDate" type="date" title="Fim"><input name="weeks" type="number" min="1" value="7" placeholder="Semanas"><input name="maxGamesWeek" type="number" min="1" value="2" placeholder="Jogos por semana"><input name="winPoints" type="number" min="0" value="100" placeholder="Pontos por vitória"><input name="lossPoints" type="number" min="0" value="25" placeholder="Pontos por derrota"><input name="qualifyPoints" type="number" min="0" value="700" placeholder="Pontos mínimos playoffs"><input name="playoffTeams" type="number" min="1" value="8" placeholder="Equipas nos playoffs"><textarea name="description" placeholder="Descrição"></textarea><textarea name="notes" placeholder="Notas / regras extra"></textarea><button class="btn">Criar Split</button></form></div>`:''}<div class="section-head"><div><span class="eyebrow">CAMPEONATOS</span><h2>Splits</h2></div></div><div class="split-grid">${splits.length?splits.map(s=>`<div class="split-card"><div><span class="eyebrow">${esc(s.season||'')}</span><h3>${esc(s.name)}</h3><p>${esc(s.description||'')}</p></div><div class="split-numbers"><b>${s.points} pts</b><span>${s.games} jogos · ${s.win_points}W / ${s.loss_points}L</span></div><div class="split-card-actions"><button class="btn" onclick="splitStats(${s.id})">Abrir split</button><button class="btn secondary" onclick="playoffsPage(${s.id})">Playoffs</button></div>${canCoach()?`<button class="btn danger" onclick="delSplit(${s.id})">Apagar</button>`:''}</div>`).join(''):'<div class="empty">Ainda não tens splits registados.</div>'}</div>`;if($('#sf'))$('#sf').onsubmit=async e=>{e.preventDefault();try{await api('/api/splits',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});statsPage()}catch(x){alert(x.message)}}}
async function splitStats(id){maps=maps.length?maps:await api('/api/maps');const d=await api('/api/splits/'+id),s=d.split;$('#pageTitle').textContent=s.name;const weeks=Array.from({length:s.weeks},(_,i)=>{const n=i+1,w=d.weeks.find(x=>x.week===n)||{},weekMatches=d.matches.filter(x=>x.week===n);return `<article class="split-week-card"><div class="split-week-head"><div><span class="eyebrow">SEMANA ${n}</span><h3>${esc(w.map_name||'Mapa por definir')}</h3></div>${w.map_name&&mapData[w.map_name]?`<img src="${mapData[w.map_name]}" loading="lazy" decoding="async" alt="${esc(w.map_name)}">`:''}</div><div class="week-map-select">${canCoach()?`<select id="wm${n}"><option value="">— selecionar mapa —</option>${maps.map(m=>`<option value="${m.id}" ${String(w.map_id)===String(m.id)?'selected':''}>${esc(m.name)}</option>`).join('')}</select>`:''}</div><div class="week-games">${[0,1].map(slot=>{const x=weekMatches[slot];return x?`<div class="game-card filled"><div class="game-top"><span>JOGO ${slot+1}</span><strong class="${x.result==='win'?'win':'loss'}">${x.result==='win'?'VITÓRIA':'DERROTA'}</strong></div><b>${esc(x.opponent)}</b><small>${esc(x.map_name)} · ${x.played_at||'Sem data'}</small><div class="game-actions"><button class="small-btn" onclick="matchStats(${x.id})">Ver stats</button>${canCoach()?`<button class="small-btn" onclick="editMatch(${x.id},${id})">Editar</button>`:''}</div></div>`:`<div class="game-card open"><span>JOGO ${slot+1}</span><b>Em aberto</b><small>Ainda sem resultado</small>${canCoach()?`<button class="small-btn" onclick="newMatch(${id},${n})">Adicionar jogo</button>`:''}</div>`}).join('')}</div></article>`}).join('');$('#c').innerHTML=`<div class="hero compact"><div><span class="eyebrow">${esc(s.season||'')}</span><h2>${esc(s.name)}</h2><p>${esc(s.description||'')}</p></div><div class="hero-stat"><b>${d.matches.reduce((a,x)=>a+(x.result==='win'?s.win_points:s.loss_points),0)}</b><span>pontos</span></div></div><div class="rules-grid"><div><b>${s.weeks}</b><span>semanas</span></div><div><b>${s.max_games_week}</b><span>jogos/semana</span></div><div><b>${s.win_points}</b><span>pontos vitória</span></div><div><b>${s.loss_points}</b><span>pontos derrota</span></div><div><b>${s.qualify_points}</b><span>mínimo playoffs</span></div><div><b>${s.playoff_teams}</b><span>equipas playoffs</span></div></div>${canCoach()?`<div class="card"><div class="section-head"><div><span class="eyebrow">CALENDÁRIO</span><h2>Ordem dos mapas</h2></div></div><p class="muted">Escolhe o mapa de cada semana. Depois os dois jogos ficam disponíveis por baixo.</p><div class="split-weeks">${weeks}</div><div class="form-actions"><button class="btn" onclick="saveWeeks(${id},${s.weeks})">Guardar semanas</button></div></div>`:`<div class="split-weeks">${weeks}</div>`}<div class="card"><span class="eyebrow">JOGOS DO SPLIT</span><h2>Histórico completo</h2><div class="matches-list">${d.matches.length?d.matches.map(x=>`<div class="match-row"><div class="match-week">W${x.week}</div><div class="match-main"><b>${esc(x.map_name)} · vs ${esc(x.opponent)}</b><small>${x.played_at||'Sem data'}</small></div><strong class="${x.result==='win'?'win':'loss'}">${x.result==='win'?'VITÓRIA':'DERROTA'}</strong><span>${x.result==='win'?s.win_points:s.loss_points} pts</span>${canCoach()?`<button class="small-btn" onclick="editMatch(${x.id},${id})">Editar</button><button class="icon-btn" onclick="delMatch(${x.id},${id})">×</button>`:''}</div>`).join(''):'<div class="empty">Ainda não há jogos neste split.</div>'}</div></div>`}
async function newMatch(splitId,week){await matchEditor(splitId,null,week)}
async function editMatch(matchId,splitId){await matchEditor(splitId,matchId)}
async function matchEditor(splitId,matchId,defaultWeek){maps=maps.length?maps:await api('/api/maps');players=await api('/api/players');let existing=null,stats=[];if(matchId){existing=await api('/api/matches/'+matchId);stats=await api('/api/matches/'+matchId+'/stats')}const week=existing?.week||defaultWeek||1;$('#pageTitle').textContent=matchId?'Editar jogo':'Adicionar jogo';$('#c').innerHTML=`<div class="card"><div class="section-head"><div><span class="eyebrow">${matchId?'EDITAR RESULTADO':'NOVO JOGO'}</span><h2>${matchId?'Editar jogo':'Adicionar resultado'}</h2></div></div><form id="mf" class="form-grid"><select name="week" required>${Array.from({length:(await api('/api/splits/'+splitId)).split.weeks},(_,i)=>`<option value="${i+1}" ${i+1===week?'selected':''}>Semana ${i+1}</option>`).join('')}</select><select name="mapId" required>${maps.map(m=>`<option value="${m.id}" ${String(existing?.map_id)===String(m.id)?'selected':''}>${esc(m.name)}</option>`).join('')}</select><input name="opponent" placeholder="Adversário" value="${esc(existing?.opponent||'')}" required><select name="result"><option value="win" ${existing?.result!=='loss'?'selected':''}>Vitória</option><option value="loss" ${existing?.result==='loss'?'selected':''}>Derrota</option></select><input name="playedAt" type="date" value="${esc(existing?.played_at||'')}"><textarea name="notes" placeholder="Notas do jogo">${esc(existing?.notes||'')}</textarea><div id="matchPlayers" class="match-stats-form"></div><div class="form-actions"><button class="btn">${matchId?'Guardar alterações':'Guardar resultado + stats'}</button><button type="button" class="btn secondary" onclick="splitStats(${splitId})">Cancelar</button></div></form></div>`;$('#matchPlayers').innerHTML=`<h3>Estatísticas dos jogadores</h3>${players.map(p=>{const q=stats.find(x=>x.player_id===p.id)||{};return `<div class="player-stat-block"><div class="stat-player"><b>${esc(p.display_name)}</b></div><input id="a${p.id}" placeholder="Agente" value="${esc(q.agent||'')}"><input id="k${p.id}" type="number" min="0" placeholder="Kills" value="${q.kills??''}"><input id="d${p.id}" type="number" min="0" placeholder="Deaths" value="${q.deaths??''}"><input id="as${p.id}" type="number" min="0" placeholder="Assists" value="${q.assists??''}"><input id="acs${p.id}" type="number" min="0" step="0.1" placeholder="ACS" value="${q.acs??''}"><input id="adr${p.id}" type="number" min="0" step="0.1" placeholder="ADR" value="${q.adr??''}"><input id="hs${p.id}" type="number" min="0" max="100" step="0.1" placeholder="HS%" value="${q.hs_pct??''}"><input id="fk${p.id}" type="number" min="0" placeholder="First Kills" value="${q.first_kills??''}"><input id="fd${p.id}" type="number" min="0" placeholder="First Deaths" value="${q.first_deaths??''}"><input id="cl${p.id}" type="number" min="0" placeholder="Clutches" value="${q.clutches??''}"><input id="pl${p.id}" type="number" min="0" placeholder="Plants" value="${q.plants??''}"><input id="df${p.id}" type="number" min="0" placeholder="Defuses" value="${q.defuses??''}"><input id="n${p.id}" placeholder="Notas" value="${esc(q.notes||'')}"></div>`}).join('')}`;$('#mf').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));data.players=players.map(p=>({playerId:p.id,agent:$('#a'+p.id)?.value,kills:$('#k'+p.id)?.value,deaths:$('#d'+p.id)?.value,assists:$('#as'+p.id)?.value,acs:$('#acs'+p.id)?.value,adr:$('#adr'+p.id)?.value,hsPct:$('#hs'+p.id)?.value,firstKills:$('#fk'+p.id)?.value,firstDeaths:$('#fd'+p.id)?.value,clutches:$('#cl'+p.id)?.value,plants:$('#pl'+p.id)?.value,defuses:$('#df'+p.id)?.value,notes:$('#n'+p.id)?.value}));try{await api(matchId?'/api/matches/'+matchId:'/api/splits/'+splitId+'/matches',{method:matchId?'PUT':'POST',body:JSON.stringify(matchId?{...data,splitId,matchId}:data)});splitStats(splitId)}catch(x){alert(x.message)}}}
function renderMatchPlayers(){if(!$('#matchPlayers'))return;$('#matchPlayers').innerHTML=`<h3>Estatísticas dos jogadores</h3>${players.map(p=>`<div class="player-stat-block"><div class="stat-player"><b>${esc(p.display_name)}</b></div><input id="a${p.id}" placeholder="Agente"><input id="k${p.id}" type="number" min="0" placeholder="Kills"><input id="d${p.id}" type="number" min="0" placeholder="Deaths"><input id="as${p.id}" type="number" min="0" placeholder="Assists"><input id="acs${p.id}" type="number" min="0" step="0.1" placeholder="ACS"><input id="adr${p.id}" type="number" min="0" step="0.1" placeholder="ADR"><input id="hs${p.id}" type="number" min="0" max="100" step="0.1" placeholder="HS%"><input id="fk${p.id}" type="number" min="0" placeholder="First Kills"><input id="fd${p.id}" type="number" min="0" placeholder="First Deaths"><input id="cl${p.id}" type="number" min="0" placeholder="Clutches"><input id="pl${p.id}" type="number" min="0" placeholder="Plants"><input id="df${p.id}" type="number" min="0" placeholder="Defuses"><input id="n${p.id}" placeholder="Notas"></div>`).join('')}`}
async function saveWeeks(id,n){const weeks=Array.from({length:n},(_,i)=>({week:i+1,mapId:$('#wm'+(i+1)).value||null}));await api('/api/splits/'+id+'/weeks',{method:'POST',body:JSON.stringify({weeks})});splitStats(id)}async function matchStats(id){const x=await api('/api/matches/'+id+'/stats');alert(x.map(p=>`${p.display_name}: ${p.kills}/${p.deaths}/${p.assists} · ACS ${p.acs} · ADR ${p.adr} · HS ${p.hs_pct}%`).join('\n')||'Sem stats.')}
