async function editTraining(id){const d=await api('/api/training/'+id);maps=maps.length?maps:await api('/api/maps');players=await api('/api/players');const old=document.querySelector('.agent-modal');if(old)old.remove();document.body.insertAdjacentHTML('beforeend',`<div class="agent-modal modal-card"><div class="agent-modal-inner training-edit-modal"><button class="icon-btn agent-close" onclick="this.closest('.agent-modal').remove()">×</button><span class="eyebrow">EDITAR TREINO</span><h2>${esc(d.match.map_name)} · ${esc(d.match.opponent)}</h2><form id="etf" class="form-grid"><select name="mapId" required>${maps.map(m=>`<option value="${m.id}" ${String(m.id)===String(d.match.map_id)?'selected':''}>${esc(m.name)}</option>`).join('')}</select><input name="opponent" placeholder="Equipa / adversário" value="${esc(d.match.opponent||'')}" required><select name="result"><option value="win" ${d.match.result==='win'?'selected':''}>Vitória</option><option value="loss" ${d.match.result==='loss'?'selected':''}>Derrota</option></select><input name="playedAt" type="date" value="${esc(d.match.played_at||'')}"><input name="notes" placeholder="Notas" value="${esc(d.match.notes||'')}"/><div class="training-stats-entry">${players.map(p=>{const q=d.stats.find(x=>x.player_id===p.id)||{};return `<div class="training-player"><div class="training-player-head"><b>${esc(p.display_name)}</b><span>Estatísticas</span></div><div class="training-fields"><input name="ta${p.id}" placeholder="Agente" value="${esc(q.agent||'')}"><input name="tk${p.id}" type="number" min="0" placeholder="K" value="${q.kills??0}"><input name="td${p.id}" type="number" min="0" placeholder="D" value="${q.deaths??0}"><input name="ta2${p.id}" type="number" min="0" placeholder="A" value="${q.assists??0}"><input name="tc${p.id}" type="number" min="0" placeholder="ACS" value="${q.acs??0}"><input name="tr${p.id}" type="number" min="0" step="0.1" placeholder="ADR" value="${q.adr??0}"><input name="th${p.id}" type="number" min="0" max="100" step="0.1" placeholder="HS%" value="${q.hs_pct??0}"><input name="tfk${p.id}" type="number" min="0" placeholder="FK" value="${q.first_kills??0}"><input name="tfd${p.id}" type="number" min="0" placeholder="FD" value="${q.first_deaths??0}"><input name="tcl${p.id}" type="number" min="0" placeholder="Clutch" value="${q.clutches??0}"><input name="tpl${p.id}" type="number" min="0" placeholder="Plant" value="${q.plants??0}"><input name="tdf${p.id}" type="number" min="0" placeholder="Defuse" value="${q.defuses??0}"><input name="tt${p.id}" type="number" min="0" placeholder="Trades" value="${q.trades??0}"><input name="tkast${p.id}" type="number" min="0" max="100" step="0.1" placeholder="KAST %" value="${q.kast_pct??0}"><input name="tn${p.id}" placeholder="Notas" value="${esc(q.notes||'')}"></div></div>`}).join('')}</div><div class="form-actions"><button class="btn">Guardar alterações</button><button type="button" class="btn secondary" onclick="this.closest('.agent-modal').remove()">Cancelar</button></div></form></div></div>`);$('#etf').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),data={mapId:f.get('mapId'),opponent:f.get('opponent'),result:f.get('result'),playedAt:f.get('playedAt'),notes:f.get('notes'),players:players.map(p=>({playerId:p.id,agent:f.get('ta'+p.id),kills:f.get('tk'+p.id),deaths:f.get('td'+p.id),assists:f.get('ta2'+p.id),acs:f.get('tc'+p.id),adr:f.get('tr'+p.id),hsPct:f.get('th'+p.id),firstKills:f.get('tfk'+p.id),firstDeaths:f.get('tfd'+p.id),clutches:f.get('tcl'+p.id),plants:f.get('tpl'+p.id),defuses:f.get('tdf'+p.id),trades:f.get('tt'+p.id),kast:f.get('tkast'+p.id),notes:f.get('tn'+p.id)}))};await api('/api/training/'+id,{method:'PUT',body:JSON.stringify(data)});document.querySelector('.agent-modal')?.remove();trainingPage()}}
async function delTraining(id){if(confirm('Apagar este jogo de treino?')){await api('/api/training/'+id,{method:'DELETE'});trainingPage()}}
async function playoffsPage(splitId){const d=await api('/api/splits/'+splitId),br=await api('/api/playoffs/'+splitId);const s=d.split;$('#pageTitle').textContent='Playoffs · '+s.name;if(!br.length&&canCoach()){$('#c').innerHTML=`<div class="page-intro"><div><span class="eyebrow">CHAVEAMENTO</span><h2>Preparar Playoffs</h2><p>Insere as ${s.playoff_teams} equipas qualificadas. O chaveamento pode ser alterado a qualquer momento.</p></div></div><div class="card"><form id="pf" class="playoff-team-form">${Array.from({length:s.playoff_teams},(_,i)=>`<div class="seed-input"><span>#${i+1}</span><input name="t${i}" placeholder="Equipa ${i+1}"></div>`).join('')}<button class="btn">Criar chaveamento</button></form></div>`;$('#pf').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);await api('/api/playoffs/'+splitId+'/setup',{method:'POST',body:JSON.stringify({teams:Array.from({length:s.playoff_teams},(_,i)=>f.get('t'+i)||'')})});playoffsPage(splitId)};return}$('#c').innerHTML=`<div class="page-intro"><div><span class="eyebrow">PLAYOFFS</span><h2>${esc(s.name)}</h2><p>${s.playoff_teams} equipas · edição manual do chaveamento e dos vencedores.</p></div></div><div class="bracket">${['QF','SF','F'].map((r,ri)=>`<section class="bracket-round"><span class="eyebrow">${r==='QF'?'QUARTER-FINALS':r==='SF'?'SEMI-FINALS':'FINAL'}</span>${br.filter(x=>x.round===r).map(m=>`<div class="bracket-match"><div class="match-label">JOGO ${m.match_no}</div><input id="a${m.id}" value="${esc(m.team_a||'')}" placeholder="Equipa A"><input id="b${m.id}" value="${esc(m.team_b||'')}" placeholder="Equipa B"><select id="w${m.id}"><option value="">Vencedor</option>${[m.team_a,m.team_b].filter(Boolean).map(t=>`<option ${m.winner===t?'selected':''}>${esc(t)}</option>`).join('')}</select><input id="r${m.id}" value="${esc(m.result||'')}" placeholder="Resultado (ex. 2-0)"><button class="small-btn" onclick="savePlayoffMatch(${m.id},${splitId})">Guardar</button></div>`).join('')}</section>`).join('')}</div>`}
async function savePlayoffMatch(id,splitId){await api('/api/playoffs/match/'+id,{method:'PUT',body:JSON.stringify({teamA:$('#a'+id).value,teamB:$('#b'+id).value,winner:$('#w'+id).value,result:$('#r'+id).value})});playoffsPage(splitId)}
async function achievementsPage(){window.vortexRefresh=achievementsPage;const items=await api('/api/achievements');$('#pageTitle').textContent='Palmarés';$('#c').innerHTML=`<div class="page-intro"><div><span class="eyebrow">VITRINE DA EQUIPA</span><h2>O que já ganhámos</h2><p>Cada conquista ocupa um lugar na nossa vitrine.</p></div></div>${canCoach()?`<div class="card trophy-form-card"><div class="trophy-form-icon">🏆</div><div><span class="eyebrow">NOVA CONQUISTA</span><h2>Adicionar troféu</h2><form id="af" class="form-grid"><input name="name" placeholder="Nome do campeonato" required><input name="achievementDate" type="date" required><button class="btn">Colocar na vitrine</button></form></div></div>`:''}<div class="trophy-shelf">${Array.from({length:Math.max(6,items.length)},(_,i)=>{const x=items[i];return `<div class="shelf-slot ${x?'filled':''}">${x?`<div class="shelf-trophy">🏆</div><b>${esc(x.name)}</b><small>${new Date(x.achievement_date+'T00:00:00').toLocaleDateString('pt-PT')}</small>${canCoach()?`<button class="icon-btn" onclick="delAchievement(${x.id})">×</button>`:''}`:'<span class="empty-trophy">＋</span>'}</div>`}).join('')}</div>`;if($('#af'))$('#af').onsubmit=async e=>{e.preventDefault();await api('/api/achievements',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});achievementsPage()}}
async function delAchievement(id){if(confirm('Apagar esta conquista?')){await api('/api/achievements/'+id,{method:'DELETE'});achievementsPage()}}
async function playersPage(){window.vortexRefresh=playersPage;players=await api('/api/players');$('#pageTitle').textContent='Credenciais';$('#c').innerHTML=`<div class="card"><span class="eyebrow">CONTAS</span><h2>Criar credencial</h2><form id="np" class="form-grid"><input name="displayName" placeholder="Nome" required><input name="username" placeholder="Username" required><input name="password" placeholder="Password" minlength="6" required><select name="role"><option value="player">Player</option><option value="coach">Coach</option><option value="both">Coach + Player</option></select><button class="btn">Criar conta</button></form></div><div class="card"><h2>Contas da equipa</h2>${players.map(p=>`<div class="account"><div class="avatar">${esc(p.display_name[0])}</div><div><b>${esc(p.display_name)}</b><small>@${esc(p.username)} · ${esc(p.role)}</small></div><button class="small-btn" onclick="resetPlayerPassword(${p.id},'${esc(p.display_name)}')">Redefinir senha</button><button class="btn danger" onclick="delP(${p.id})">Apagar</button></div>`).join('')||'<p class="muted">Sem contas.</p>'}</div>`;$('#np').onsubmit=async e=>{e.preventDefault();try{await api('/api/players',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});playersPage()}catch(x){alert(x.message)}}}
async function resetPlayerPassword(id,name){const next=prompt('Nova palavra-passe para '+name+' (mín. 6 caracteres):');if(next===null)return;if(next.length<6)return alert('A palavra-passe deve ter pelo menos 6 caracteres.');try{await api('/api/players/'+id+'/password',{method:'POST',body:JSON.stringify({newPassword:next})});alert('Palavra-passe redefinida com sucesso.')}catch(x){alert(x.message)}}
async function delP(id){if(confirm('Apagar esta conta?')){await api('/api/players/'+id,{method:'DELETE'});playersPage()}}
async function analyzerPage(){
 window.vortexRefresh=analyzerPage;
 try{
  const [d,tl,vods]=await Promise.all([api('/api/analysis'),api('/api/analysis/timeline'),api('/api/analysis/vods')]);
  $('#pageTitle').textContent='Analisador';
  const cards=(d.players||[]).map(x=>{const kd=x.deaths?x.kills/x.deaths:x.kills,kast=Number(x.kast_pct||0),trades=Number(x.trades||0);return `<article class="analysis-player"><div class="analysis-main"><div class="analysis-name"><b>${esc(x.display_name)}</b><span>${esc(x.role||'Sem função')} · ${x.matches} jogos</span></div><div class="analysis-bars"><b>K/D ${kd.toFixed(2)}</b><b>ACS ${Number(x.acs||0).toFixed(0)}</b><b>ADR ${Number(x.adr||0).toFixed(0)}</b><b>KAST ${kast.toFixed(1)}%</b><b>Trades ${trades.toFixed(1)}</b></div><button class="small-btn" onclick="playerReport(${x.id||''})">Ver relatório individual</button></div></article>`}).join('');
  const maps=(d.maps||[]).map(x=>`<div class="analysis-map"><b>${esc(x.map_name)}</b><span>${x.wins}W · ${x.losses}L · ${x.winrate.toFixed(0)}%</span></div>`).join('');
  const byType=Object.entries(tl.summary?.byType||{}).map(([k,v])=>`<span class="timeline-chip">${esc(k)} <b>${v}</b></span>`).join('');
  $('#c').innerHTML=`<section class="hero neon-hero"><span class="eyebrow">VORTEX PERFORMANCE LAB</span><h2>Análise com contexto</h2><p>O Analyzer cruza estatísticas, função competitiva e timeline. IGL, Iniciadores e restantes funções são avaliados pelo contexto; K/D ou KAST isolados não decidem uma conclusão.</p></section>
  <div class="analysis-summary"><div class="analysis-kpi"><span>Jogos</span><b>${d.matches||0}</b></div><div class="analysis-kpi"><span>Winrate</span><b>${Number(d.winrate||0).toFixed(1)}%</b></div><div class="analysis-kpi"><span>K/D</span><b>${Number(d.kd||0).toFixed(2)}</b></div><div class="analysis-kpi"><span>KAST</span><b>${Number(d.kast||0).toFixed(1)}%</b></div><div class="analysis-kpi"><span>Trades</span><b>${Number(d.trades||0).toFixed(1)}</b></div></div>
  <div class="analysis-tools-grid"><section class="card analyzer-tool"><div class="section-head"><div><span class="eyebrow">01 · TIMELINE</span><h2>Importar cronologia</h2></div></div><p>Cola JSON de eventos. A timeline permite encontrar padrões de timing, First Deaths, First Kills e trades.</p><textarea id="timelineJson" class="timeline-input" placeholder='[{"time":12,"round":1,"player":"Nome","type":"first_death"}]'></textarea><div class="tool-actions">${canCoach()?'<button class="btn" onclick="importTimeline()">Importar timeline</button><button class="small-btn danger" onclick="clearTimeline()">Limpar</button>':''}</div></section>
  <section class="card analyzer-tool"><div class="section-head"><div><span class="eyebrow">02 · VOD</span><h2>Associar VOD</h2></div></div><p>Guarda a VOD no servidor local. Para conclusões táticas automáticas, importa também a timeline.</p>${canCoach()?'<input id="vodFile" type="file" accept="video/*"><input id="vodNotes" placeholder="Notas da VOD / adversário"><button class="btn" onclick="uploadVod()">Guardar VOD</button>':'<div class="empty">Apenas Coach/Admin pode associar VODs.</div>'}<div class="vod-list">${vods.length?vods.map(v=>`<div><b>${esc(v.original_name)}</b><small>${(v.size_bytes/1024/1024).toFixed(1)} MB · ${esc(v.uploaded_at||'')}</small></div>`).join(''):'<span class="muted">Nenhuma VOD guardada.</span>'}</div></section></div>
  <section class="card"><div class="section-head"><div><span class="eyebrow">TIMELINE REPORT</span><h2>${tl.summary?.events||0} eventos analisados</h2></div></div><div class="timeline-chips">${byType||'<span class="muted">Sem eventos.</span>'}</div></section>
  <div class="section-head"><h2>Relatórios individuais</h2></div><div class="analysis-players">${cards||'<div class="empty">Ainda não existem estatísticas.</div>'}</div>
  <div class="section-head"><h2>Performance por mapa</h2></div><div class="analysis-map-grid">${maps||'<div class="empty">Ainda não existem jogos.</div>'}</div>`;
 }catch(e){$('#c').innerHTML=`<div class="card error-card"><h2>Erro no analisador</h2><p>${esc(e.message||'Erro desconhecido')}</p><button class="btn" onclick="analyzerPage()">Tentar novamente</button></div>`}
}
async function importTimeline(){try{const raw=$('#timelineJson').value.trim();if(!raw)throw Error('Cola a timeline primeiro.');const data=JSON.parse(raw);if(!Array.isArray(data)&&!Array.isArray(data.events))throw Error('A timeline deve ser um array JSON.');await api('/api/analysis/timeline',{method:'POST',body:JSON.stringify({events:Array.isArray(data)?data:data.events})});alert('Timeline importada.');analyzerPage()}catch(e){alert(e.message)}}
async function clearTimeline(){if(!confirm('Apagar toda a timeline importada?'))return;await api('/api/analysis/timeline',{method:'DELETE'});analyzerPage()}
async function uploadVod(){try{const f=$('#vodFile')?.files?.[0];if(!f)throw Error('Escolhe uma VOD.');const fd=new FormData();fd.append('vod',f);fd.append('notes',$('#vodNotes')?.value||'');const r=await fetch('/api/analysis/vod',{method:'POST',body:fd,credentials:'same-origin'});const d=await r.json();if(!r.ok)throw Error(d.error||'Erro ao guardar VOD');alert(d.message||'VOD guardada.');analyzerPage()}catch(e){alert(e.message)}}
async function playerReport(id){try{const d=await api('/api/analysis/report/'+id),s=d.stats,t=d.timeline;$('#c').innerHTML=`<section class="hero neon-hero"><span class="eyebrow">RELATÓRIO INDIVIDUAL</span><h2>${esc(d.player.display_name)}</h2><p>${esc(d.role)} · ${d.matches} jogos · confiança: ${esc(d.confidence)}</p></section><div class="analysis-summary"><div class="analysis-kpi"><span>K/D</span><b>${s.kd.toFixed(2)}</b></div><div class="analysis-kpi"><span>KAST</span><b>${s.kast.toFixed(1)}%</b></div><div class="analysis-kpi"><span>Trades</span><b>${s.trades.toFixed(1)}</b></div><div class="analysis-kpi"><span>FK / FD</span><b>${s.fk} / ${s.fd}</b></div></div><section class="card report-card"><h2>Leitura contextual</h2>${d.insights.map(x=>`<p>◆ ${esc(x)}</p>`).join('')}<div class="report-note">Factos estatísticos e padrões de timeline são separados de conclusões táticas. Uma habilidade sem dano direto, K/D baixo ou KAST baixo não determina sozinho que o jogador está a jogar mal.</div></section><section class="card"><h2>Timeline</h2><p>${t.events} eventos · ${t.firstKills} First Kills · ${t.firstDeaths} First Deaths · ${t.trades} trades.</p><button class="btn" onclick="analyzerPage()">Voltar ao Analyzer</button></section>`}catch(e){alert(e.message)}}

boot();
